def _history_parameters():
    global _HISTORY_PARAMETERS
    if _HISTORY_PARAMETERS is None:
        _HISTORY_PARAMETERS={'P':_unpack_static_fp32(_HISTORY_P0_LITERAL),
                             'Q':_unpack_static_fp32(_HISTORY_MODEL_LITERAL)}
